def licence_key_to_date(apps, schema_editor):
    """A licence key entered before this version becomes the valid till date."""
    import datetime as dt

    from core import licence

    AppSettings = apps.get_model("core", "AppSettings")
    for app in AppSettings.objects.using(schema_editor.connection.alias).exclude(licence_key=""):
        try:
            data = licence.decode(app.licence_key, app.install_id)
        except licence.LicenceError:
            continue
        app.sub_valid_until = dt.date.fromisoformat(data["u"])
        app.sub_max_users = int(data.get("m", 0))
        app.sub_plan = data.get("p", "")[:60]
        app.save(update_fields=["sub_valid_until", "sub_max_users", "sub_plan"])


